template.inlineTemplate:
//TSO1     EXEC PGM=IKJEFT01,DYNAMNBR=36
//SYSTSPRT DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
 RACDCERT ID(${instance-KEYRING_OWNER}) LISTRING(${instance-KEYRING_NAME})
/*

step.instructions:
This step runs an inline REXX program against keyring ${instance-KEYRING_NAME} owned by ${instance-KEYRING_OWNER}.
For every certificate connected to the keyring the report shows: - Certificate label - Owning user ID (or CERTAUTH / SITE) - Subject distinguished name (SUBJECT) - Expiry date (YYYY-MM-DD) - Days remaining until expiry - EXPIRED flag if the certificate has already expired - WARNING flag if days remaining is less than ${instance-WARN_DAYS}
A summary line at the end shows total certificates scanned, warnings raised, and expired certificates found.

template.inlineTemplate:
//KREXX    EXEC PGM=IKJEFT01,DYNAMNBR=36,REGION=0M
//SYSTSPRT DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
 EX 'ANDRE.REXX.EXEC(KEYRGAUD)' '${instance-KEYRING_OWNER} ${instance-KEYRING_NAME} ${instance-WARN_DAYS}' EXEC
/*

//KREXX    EXEC PGM=IKJEFT01,DYNAMNBR=36,REGION=0M
//SYSTSPRT DD DSN=${instance-REPORT_DATASET},DISP=SHR
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
 EX 'ANDRE.REXX.EXEC(KEYRGAUD)' '${instance-KEYRING_OWNER} ${instance-KEYRING_NAME} ${instance-WARN_DAYS}' EXEC
/*
